using NUnit.Framework;using UnityEngine;
public sealed class VerticalFloorCacheTests{
 GameObject actor;Transform rig,joint;CandidateFootGrounding g;
 [SetUp]public void Setup(){actor=new GameObject("vertical floor cache");rig=new GameObject("rig").transform;rig.SetParent(actor.transform,false);joint=new GameObject("joint").transform;joint.SetParent(rig,false);g=actor.AddComponent<CandidateFootGrounding>();g.nativeRig=rig;g.nativeRest=Vector3.zero;g.bones=new[]{joint};g.shoePoints=new[]{new CandidateFootGrounding.Point{influences=new[]{new CandidateFootGrounding.Influence{bone=0,bindPoint=new Vector3(.2f,-.2f,.3f),weight=1}}}};}
 [TearDown]public void Cleanup(){Object.DestroyImmediate(actor);}
 [Test]public void HorizontalWorldMotionRetainsExactFloorWithoutRescan(){float floor=g.MeasureMinimum();int before=g.MinimumEvaluationCount;for(int i=0;i<50;i++){actor.transform.position=new Vector3(i*.13f,0,-i*.27f);Assert.AreEqual(floor,g.MeasureMinimum());}Assert.AreEqual(before,g.MinimumEvaluationCount,"Horizontal-only world motion does not change the world-Y floor equation");}
 [Test]public void HorizontalLocalMotionUnderTiltedParentStillInvalidatesFloor(){actor.transform.rotation=Quaternion.Euler(0,0,35);float floor=g.MeasureMinimum();int before=g.MinimumEvaluationCount;joint.localPosition=Vector3.right*.4f;float next=g.MeasureMinimum();Assert.AreNotEqual(floor,next);Assert.AreEqual(before+1,g.MinimumEvaluationCount);}
 [Test]public void SubEpsilonVerticalChangeInvalidatesExactly(){float old=g.MeasureMinimum();int count=g.MinimumEvaluationCount;joint.localPosition=Vector3.up*.0000001f;float next=g.MeasureMinimum();Assert.AreEqual(count+1,g.MinimumEvaluationCount,"Unity approximate Vector4 operator must not validate this cache");Assert.AreNotEqual(old,next);}
 [Test]public void WeightedMinimumIsBitExactAcrossScaleShearAndPoseChanges(){var other=new GameObject("other").transform;other.SetParent(rig,false);g.bones=new[]{joint,other};var random=new System.Random(77219);System.Func<float> next=()=>(float)random.NextDouble();var points=new CandidateFootGrounding.Point[127];for(int n=0;n<points.Length;n++){float w=next();points[n]=new CandidateFootGrounding.Point{influences=new[]{new CandidateFootGrounding.Influence{bone=0,bindPoint=new Vector3(next(),next()-.7f,next()),weight=w},new CandidateFootGrounding.Influence{bone=1,bindPoint=new Vector3(next(),next()-.7f,next()),weight=1-w}}};}g.shoePoints=points;for(int n=0;n<256;n++){actor.transform.position=new Vector3(next(),next()-.5f,next());actor.transform.rotation=Quaternion.Euler(next()*180,next()*180,next()*180);actor.transform.localScale=new Vector3(.3f+next(),.4f+next(),.5f+next());joint.localRotation=Quaternion.Euler(next()*200,next()*200,next()*200);other.localPosition=new Vector3(next(),next(),next());other.localRotation=Quaternion.Euler(next()*200,next()*200,next()*200);g.ResetForSample();float expected=float.PositiveInfinity;foreach(var point in points){float y=0;foreach(var influence in point.influences){var m=g.bones[influence.bone].localToWorldMatrix;var p=influence.bindPoint;y+=(m.m10*p.x+m.m11*p.y+m.m12*p.z+m.m13)*influence.weight;}expected=Mathf.Min(expected,y);}float actual=g.MeasureMinimum();Assert.AreEqual(System.BitConverter.SingleToInt32Bits(expected),System.BitConverter.SingleToInt32Bits(actual),"Pose "+n);}}
}
